"""Evaluate BEVFusion on a config generated by make_weather_config.py.

tools/test.py loads configs through torchpack, which expects the YAML config
hierarchy. make_weather_config.py writes an already-resolved mmcv config.py, so
this script loads it with mmcv.Config.fromfile and otherwise mirrors
tools/test.py on a single GPU (no torchpack launcher needed).

Writes to --out-dir (default: the config's directory):
  metrics.json        all nuScenes metrics plus the run settings
  nusc/               nuScenes devkit outputs (results_nusc.json, metrics_summary.json)
  results.pkl         raw predictions (only with --save-results)

Example:
  python tools/weather_eval/run_eval.py \
    work_dirs/weather_full/fog_060/config.py pretrained/bevfusion-det.pth
"""
import argparse
import json
from pathlib import Path
import sys
import time

REPO_ROOT = Path(__file__).resolve().parents[2]
if str(REPO_ROOT) not in sys.path:
  sys.path.insert(0, str(REPO_ROOT))

import mmcv  # noqa: E402
import torch  # noqa: E402
from mmcv import Config  # noqa: E402
from mmcv.parallel import MMDataParallel  # noqa: E402
from mmcv.runner import load_checkpoint, wrap_fp16_model  # noqa: E402
from mmdet.apis import set_random_seed  # noqa: E402

from mmdet3d.apis import single_gpu_test  # noqa: E402
from mmdet3d.datasets import build_dataloader, build_dataset  # noqa: E402
from mmdet3d.models import build_model  # noqa: E402


def parse_args():
  parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
  parser.add_argument("config", help="Generated config.py")
  parser.add_argument("checkpoint", help="BEVFusion checkpoint (.pth)")
  parser.add_argument(
      "--out-dir", default=None, help="Output directory (default: config's dir)"
  )
  parser.add_argument(
      "--workers", type=int, default=4, help="Dataloader workers (default: 4)"
  )
  parser.add_argument("--seed", type=int, default=0, help="Torch/numpy seed")
  parser.add_argument(
      "--save-results", action="store_true", help="Also write raw results.pkl"
  )
  parser.add_argument(
      "--skip-existing",
      action="store_true",
      help="Do nothing if metrics.json already exists in the output directory",
  )
  return parser.parse_args()


def _weather_step(pipeline):
  for op in pipeline or []:
    if isinstance(op, dict) and op.get("type") == "WeatherDegradation":
      return op
  return None


def main():
  args = parse_args()
  cfg_path = Path(args.config)
  out_dir = Path(args.out_dir) if args.out_dir else cfg_path.parent
  out_dir.mkdir(parents=True, exist_ok=True)
  metrics_path = out_dir / "metrics.json"
  if args.skip_existing and metrics_path.exists():
    print(f"Skipping: {metrics_path} exists")
    return

  cfg = Config.fromfile(str(cfg_path))  # also runs cfg.custom_imports
  set_random_seed(args.seed)
  torch.backends.cudnn.benchmark = True

  cfg.model.pretrained = None
  cfg.model.train_cfg = None
  cfg.data.test.test_mode = True
  cfg.data.test.pop("samples_per_gpu", None)

  step = _weather_step(cfg.data.test.get("pipeline"))
  if step is None:
    raise RuntimeError("No WeatherDegradation step in data.test.pipeline")

  dataset = build_dataset(cfg.data.test)
  loader = build_dataloader(
      dataset,
      samples_per_gpu=1,
      workers_per_gpu=args.workers,
      dist=False,
      shuffle=False,
  )

  model = build_model(cfg.model, test_cfg=cfg.get("test_cfg"))
  if cfg.get("fp16", None) is not None:
    wrap_fp16_model(model)
  checkpoint = load_checkpoint(model, args.checkpoint, map_location="cpu")
  model.CLASSES = checkpoint.get("meta", {}).get("CLASSES", dataset.CLASSES)
  model = MMDataParallel(model.cuda(), device_ids=[0])

  print(
      f"Evaluating {len(dataset)} samples | weather={step.get('weather')} "
      f"severity={step.get('severity')} modality={step.get('modality', 'both')} "
      f"seed={step.get('seed')}"
  )
  start = time.time()
  outputs = single_gpu_test(model, loader)
  elapsed = time.time() - start

  if args.save_results:
    mmcv.dump(outputs, str(out_dir / "results.pkl"))

  metrics = dataset.evaluate(
      outputs, metric="bbox", jsonfile_prefix=str(out_dir / "nusc")
  )
  record = dict(
      config=str(cfg_path),
      checkpoint=str(args.checkpoint),
      dataset_version=getattr(dataset, "version", None),
      num_samples=len(dataset),
      weather=step.get("weather"),
      severity=step.get("severity"),
      modality=step.get("modality", "both"),
      degradation_seed=step.get("seed"),
      inference_seconds=round(elapsed, 1),
      mAP=metrics.get("object/map"),
      NDS=metrics.get("object/nds"),
      metrics={k: float(v) for k, v in metrics.items()},
  )
  metrics_path.write_text(json.dumps(record, indent=2))
  print(f"mAP={record['mAP']:.4f} NDS={record['NDS']:.4f} -> {metrics_path}")


if __name__ == "__main__":
  main()
